  [23780] = { "$D1の間アーマーを$N1上昇させ、遠隔または近接ダメージを受けるたびに$N2のダメージを回復します。", "アーマーが$N1増加しています。\n遠隔または近接のダメージを受けるたびに、$N2のダメージを回復します。", 0x03574ef4, 0xc6e0d127, "uu" },
